The plugin contract:
```ts
import type { Plugin, PluginContext } from "../../kernel/types";

const plugin: Plugin = {
  id: "result-panel",
  name: "Result Panel",
  version: "1.0.0",
  onLoad(ctx: PluginContext) {
    ctx.register({
      kind: "api",
      mount: "panel",
      router: () => ({ title: "Panel", html: "<p>value=29</p>" }),
    });
  },
};
export default plugin;
```

